var rows = msg.payload || [];
if (!Array.isArray(rows) || rows.length === 0) {
    return {
        payload: [{
            series: ["Member", "Casual"],
            data: [[0], [0]],
            labels: ["No data"]
        }]
    };
}

var bucketsSet = new Set();
var memberMap = {};
var casualMap = {};

rows.forEach(function(r) {
    var b = r.time_bucket;
    bucketsSet.add(b);
    if (r.member_casual === 'member') memberMap[b] = r.trip_count;
    else if (r.member_casual === 'casual') casualMap[b] = r.trip_count;
});

var sortedBuckets = Array.from(bucketsSet).sort();
var memberData = [];
var casualData = [];

sortedBuckets.forEach(function(b) {
    memberData.push(memberMap[b] || 0);
    casualData.push(casualMap[b] || 0);
});

return {
    payload: [{
        series: ["Member", "Casual"],
        data: [memberData, casualData],
        labels: sortedBuckets
    }]
};

var rows = msg.payload || [];
var labels = [];
var energyData = [];
var totalKwh = 0;
var totalEbikeTrips = 0;

if (Array.isArray(rows) && rows.length > 0) {
    rows.forEach(function(r) {
        labels.push(r.trip_date);
        var kwh = Number(r.total_energy_kwh || 0);
        energyData.push(kwh);
        totalKwh += kwh;
        totalEbikeTrips += Number(r.ebike_trips || 0);
    });
} else {
    labels = ["No Data"];
    energyData = [0];
}

var avgKwh = totalEbikeTrips > 0 ? (totalKwh / totalEbikeTrips).toFixed(3) : "0.000";

var kpiCard = {
    payload: "Total: " + totalKwh.toFixed(1) + " kWh | E-Bikes: " + totalEbikeTrips + " | Avg: " + avgKwh + " kWh/trip"
};

var chartPayload = {
    payload: [{
        series: ["kWh"],
        data: [energyData],
        labels: labels
    }]
};

return [kpiCard, chartPayload];

var rows = msg.payload || [];
var totalTrips = 0;
var totalHours = 0;
var b1 = 0, b2 = 0, b3 = 0, b4 = 0, b5 = 0;

if (Array.isArray(rows) && rows.length > 0) {
    rows.forEach(function(r) {
        totalTrips += Number(r.total_trips || 0);
        totalHours += Number(r.total_hours || 0);
        b1 += Number(r.under_5m || 0);
        b2 += Number(r.m5_to_15m || 0);
        b3 += Number(r.m15_to_30m || 0);
        b4 += Number(r.m30_to_60m || 0);
        b5 += Number(r.over_60m || 0);
    });
}

var avgDuration = totalTrips > 0 ? ((totalHours * 60) / totalTrips).toFixed(1) : "0.0";

var kpiCard = {
    payload: "Total: " + totalHours.toFixed(1) + " h | Avg: " + avgDuration + " min | Trips: " + totalTrips
};

var chartPayload = {
    payload: [{
        series: ["Trips"],
        data: [[b1, b2, b3, b4, b5]],
        labels: ["< 5m", "5-15m", "15-30m", "30-60m", "> 60m"]
    }]
};

return [kpiCard, chartPayload];

var rows = msg.payload || [];
var labels = [
    "Morning (07-10h)",
    "Midday (10-16h)",
    "Evening (16-19h)",
    "Night (19-07h)"
];
var counts = [0, 0, 0, 0];

if (Array.isArray(rows) && rows.length > 0) {
    rows.forEach(function(r) {
        var w = r.time_window || '';
        var cnt = Number(r.trip_count || 0);
        if (w.indexOf('Morning') !== -1) counts[0] = cnt;
        else if (w.indexOf('Midday') !== -1) counts[1] = cnt;
        else if (w.indexOf('Evening') !== -1) counts[2] = cnt;
        else if (w.indexOf('Night') !== -1) counts[3] = cnt;
    });
}

return {
    payload: [{
        series: ["Trips"],
        data: counts,
        labels: labels
    }]
};

var rows = msg.payload || [];
var datesSet = new Set();
var memberMap = {};
var casualMap = {};
var totalMemberRev = 0;
var totalCasualRev = 0;

if (Array.isArray(rows) && rows.length > 0) {
    rows.forEach(function(r) {
        var d = r.trip_date;
        datesSet.add(d);
        var rev = Number(r.total_revenue_usd || 0);
        if (r.member_casual === 'member') {
            memberMap[d] = rev;
            totalMemberRev += rev;
        } else if (r.member_casual === 'casual') {
            casualMap[d] = rev;
            totalCasualRev += rev;
        }
    });
}

var sortedDates = Array.from(datesSet).sort();
var memberRevs = [];
var casualRevs = [];

sortedDates.forEach(function(d) {
    memberRevs.push(memberMap[d] || 0);
    casualRevs.push(casualMap[d] || 0);
});

var totalRev = totalMemberRev + totalCasualRev;

var kpiCard = {
    payload: "Total: $" + totalRev.toFixed(2) + " | Member: $" + totalMemberRev.toFixed(2) + " | Casual: $" + totalCasualRev.toFixed(2)
};

var chartPayload = {
    payload: [{
        series: ["Member ($)", "Casual ($)"],
        data: [memberRevs, casualRevs],
        labels: sortedDates.length > 0 ? sortedDates : ["No Data"]
    }]
};

return [kpiCard, chartPayload];

var rows = msg.payload || [];
if (!Array.isArray(rows) || rows.length === 0) {
    return {
        payload: "<p style='color:#888; font-size:12px; margin:0;'>No data</p>"
    };
}

var html = "<table style='width:100%; border-collapse:collapse; font-size:12px; color:#ddd;'>";
html += "<tr style='border-bottom:1px solid #444; color:#aaa; text-align:left;'>";
html += "<th style='padding:6px;'>#</th>";
html += "<th style='padding:6px;'>Station</th>";
html += "<th style='padding:6px; text-align:right;'>Departures</th>";
html += "<th style='padding:6px; text-align:right;'>E-Bike</th>";
html += "<th style='padding:6px; text-align:right;'>Member</th>";
html += "</tr>";

rows.forEach(function(r, idx) {
    var total = Number(r.departures || 0);
    var ebikes = Number(r.ebike_departures || 0);
    var members = Number(r.member_departures || 0);
    var ebikePct = total > 0 ? ((ebikes / total) * 100).toFixed(0) + "%" : "0%";
    var memberPct = total > 0 ? ((members / total) * 100).toFixed(0) + "%" : "0%";

    html += "<tr style='border-bottom:1px solid #282828;'>";
    html += "<td style='padding:6px; color:#888;'>" + (idx + 1) + "</td>";
    html += "<td style='padding:6px; font-weight:500;'>" + r.station_name + "</td>";
    html += "<td style='padding:6px; text-align:right;'>" + total + "</td>";
    html += "<td style='padding:6px; text-align:right;'>" + ebikes + " (" + ebikePct + ")</td>";
    html += "<td style='padding:6px; text-align:right;'>" + members + " (" + memberPct + ")</td>";
    html += "</tr>";
});

html += "</table>";

return { payload: html };

if (!msg.payload) return null;
var p = msg.payload;
return [
    { payload: p.active_trips || 0, topic: "active_trips" },
    { payload: p.total_bikes_avail || 0, topic: "total_bikes_avail" },
    { payload: p.total_ebikes_avail || 0, topic: "total_ebikes_avail" },
    { payload: Number((p.stage2_energy_kwh || 0).toFixed(2)), topic: "stage2_energy_kwh" },
    { payload: Number((p.stage2_avg_duration_min || 0).toFixed(1)), topic: "stage2_avg_duration_min" }
];
